{"action": "replace_code", "code": "def solve(data):
    chosen = {}
    for idx, row in enumerate(data):
        key = row['id']
        if key not in chosen:
            chosen[key] = dict(row)
        else:
            existing = chosen[key]
            if row['time'] > existing['time']:
                chosen[key] = dict(row)
            elif row['time'] == existing['time']:
                if idx > existing['idx']:
                    chosen[key] = dict(row)
    return [chosen[key] for key in sorted(chosen)]"}
